    @_sympifyit('g', NotImplemented)
    def __add__(f, g):
        if not getattr(g, 'is_Poly', False):
            try:
                g = f.__class__(g, *f.gens)
            except PolynomialError:
                return f.as_expr() + g
        return f.add(g)

    @_sympifyit('g', NotImplemented)
    def __radd__(f, g):
        if not getattr(g, 'is_Poly', False):
            try:
                g = f.__class__(g, *f.gens)
            except PolynomialError:
                return g + f.as_expr()
        return g.add(f)
''')
